from pathlib import Path
path=Path(__file__).resolve().parents[1]/'frontend/src/App.vue'
s=path.read_text(encoding='utf-8')
if 'const compareIds=' in s:
    raise SystemExit('界面改进已应用，无需重复执行。')
s=s.replace("const form=reactive(","const compareIds=ref<string[]>([]);\nconst comparison=computed(()=>{const selected=evaluations.value.filter(e=>compareIds.value.includes(e.id));if(selected.length!==2)return null;const [a,b]=selected;return {a,b,rows:a.results.map((r:Row)=>({id:r.case_id,name:r.name,before:r,after:b.results.find((x:Row)=>x.case_id===r.case_id)}))};});\nconst fieldNames:Row={hours:'有效小时',resource:'申请权限',purpose:'申请用途',sku:'软件',employee_id:'申请人编号',device_id:'设备编号'};\nconst actionNames:Row={unlock_account:'解锁业务账号',grant_permission:'开通临时权限',assign_software:'分配软件授权'};\nconst form=reactive(")
s=s.replace('<small>{{k}}</small>','<small>{{fieldNames[k]||k}}</small>').replace('<dd>{{p.action}}</dd>','<dd>{{actionNames[p.action]||p.action}}</dd>')
s=s.replace("async function openTicket(id:string){selected.value=await api('/tickets/'+id);", "async function openTicket(id:string){selected.value=await api('/tickets/'+id);if(user.value?.role==='support')users.value=await api('/users');")
s=s.replace('<button class="text-button danger" @click="mutate(\'cancel\')">取消工单</button></div></div>', '<button class="text-button danger" @click="mutate(\'cancel\')">取消工单</button></div><details v-if="user.role===\'support\'"><summary>转派给处理人员</summary><div class="chips"><button v-for="person in users.filter(x=>x.role===\'support\'&&x.active)" @click="task(async()=>{await api(\'/tickets/\'+selected!.ticket.id+\'/actions/assign\',\'POST\',{version:selected!.ticket.version,assignee_id:person.id});await openTicket(selected!.ticket.id)})">{{person.name}}</button></div></details></div>')
s=s.replace('<article v-for="e in evaluations" class="card"><div', '<article v-for="e in evaluations" class="card"><label class="inline"><input type="checkbox" :value="e.id" v-model="compareIds" :disabled="compareIds.length>=2&&!compareIds.includes(e.id)">加入对比</label><div')
s=s.replace('<div class="card"><h3>最近运行</h3>', '<div v-if="comparison" class="card"><h3>{{comparison.a.label}} → {{comparison.b.label}}</h3><p class="help">{{comparison.a.mode}} / {{comparison.b.mode}} · {{comparison.a.summary.dataset_hash===comparison.b.summary.dataset_hash?\'相同任务集\':\'任务集版本不同\'}}。请同时检查资料版本与运行模式，不将环境差异归因于模型。</p><table><thead><tr><th>任务</th><th>前一版本</th><th>后一版本</th></tr></thead><tbody><tr v-for="c in comparison.rows"><td>{{c.name}}</td><td>{{c.before.passed?\'通过\':\'未通过\'}}</td><td>{{c.after?(c.after.passed?\'通过\':\'未通过\'):\'尚未完成\'}}</td></tr></tbody></table></div><div class="card"><h3>最近运行</h3>')
path.write_text(s,encoding='utf-8')
